use serde::{Deserialize,Serialize};use serde_json::json;use std::collections::BTreeSet;use thiserror::Error;
pub const FEATURE_ID:&str="AFA-worldgen-P26-F01";pub const CONTRACT_VERSION:&str="worldgen-local-limitation-closure/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.limitation-closure-receipt-1+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct LimitationCase4{pub case_id:String,pub scope:String,pub status:String,pub evidence_digests:Vec<ContentHash>,pub replay_identity:ContentHash,pub local:bool,pub aggregate_only:bool,pub negative_result:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ClosurePeer4{pub peer_id:String,pub semantic_profile:String,pub evidence_state:String,pub closure_digest:ContentHash,pub replay_identity:ContentHash,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct LimitationClosureRequest4{pub request_id:String,pub semantic_profile:String,pub required_scope_order:Vec<String>,pub cases:Vec<LimitationCase4>,pub peers:Vec<ClosurePeer4>,pub minimum_peer_quorum:u32,pub policy_allowed:bool,pub protected_closure:bool,pub federation_approved:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub boundary:String}
