#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct LimitationClosureCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub semantic_profile:String,pub disposition:String,pub case_order:Vec<String>,pub resolved_order:Vec<String>,pub unresolved_order:Vec<String>,pub blocked_order:Vec<String>,pub peer_order:Vec<String>,pub qualified_peer_order:Vec<String>,pub missing_peer_order:Vec<String>,pub omission_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:LimitationClosureArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum LimitationClosureError{#[error("invalid limitation-closure request: {0}")]Invalid(String),#[error("limitation-closure card failed validation: {0}")]Output(String)}
fn ord(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn dig(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ne(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":id,"version":version,"owner_crate":"worldgen","consumers":["limitations scientist","federation operator","release auditor","context compiler"],"behavior":format!("close typed limitations with explicit unresolved states at {scale} ({mode})"),"value":"prevents open, contradictory, or peer-incomplete limitations from being represented as closed","input_schema":"LimitationClosureRequest4@1","output_schema":"LimitationClosureCard7@1","effects":["exchange:limitation-digests","block:unsafe-release"],"permissions":["read:local-limitation-attestations"],"determinism":"byte_stable","autonomy_tier":"A2","boundary":PRECLINICAL_BOUNDARY})}
impl LimitationClosureCard7{pub fn validate(&self)->Result<(),LimitationClosureError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||!ne(&self.semantic_profile)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.case_order.is_empty()||self.peer_order.is_empty()||!ord(&self.case_order)||!ord(&self.resolved_order)||!ord(&self.unresolved_order)||!ord(&self.blocked_order)||!ord(&self.peer_order)||!ord(&self.qualified_peer_order)||!ord(&self.missing_peer_order)||!ord(&self.omission_order)||!ord(&self.uncertainty_order)||!ord(&self.negative_evidence_order)||!dig(&self.replay_identity)||!dig(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY{return Err(LimitationClosureError::Output("closure identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.case_order.iter().cloned());let parts=self.resolved_order.iter().chain(&self.unresolved_order).chain(&self.blocked_order).cloned().collect::<Vec<_>>();if ids.len()!=self.case_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(LimitationClosureError::Output("limitation states do not partition".into()))}let pids=BTreeSet::from_iter(self.peer_order.iter().cloned());let pparts=self.qualified_peer_order.iter().chain(&self.missing_peer_order).cloned().collect::<Vec<_>>();if pids.len()!=self.peer_order.len()||pparts.len()!=pids.len()||BTreeSet::from_iter(pparts)!=pids{return Err(LimitationClosureError::Output("peer states do not partition".into()))}Ok(())}}
pub fn close(request:&LimitationClosureRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<LimitationClosureCard7,LimitationClosureError>{if !ne(&request.request_id)||!ne(&request.semantic_profile)||request.required_scope_order.is_empty()||request.cases.is_empty()||request.peers.is_empty()||request.minimum_peer_quorum==0||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_scope_order)||!ord(&request.adversarial_events){return Err(LimitationClosureError::Invalid("closure identity, scopes, cases, peers, quorum, digest, ordering, locality, or boundary is invalid".into()))}let mut cases=request.cases.clone();cases.sort_by(|a,b|a.case_id.cmp(&b.case_id));let mut peers=request.peers.clone();peers.sort_by(|a,b|a.peer_id.cmp(&b.peer_id));let mut seen=BTreeSet::new();let mut case_order=Vec::new();let mut resolved=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();for c in &cases{if !seen.insert(c.case_id.clone())||!ne(&c.case_id)||!ne(&c.scope)||!dig(&c.replay_identity)||!c.local||!c.aggregate_only{ return Err(LimitationClosureError::Invalid("case identity or locality is invalid".into()))}case_order.push(c.case_id.clone());if c.negative_result{negative.insert(format!("{}:negative-result",c.case_id));}if !request.required_scope_order.contains(&c.scope){unresolved.insert(c.case_id.clone());omissions.insert(format!("{}:scope-not-requested",c.case_id));}else if c.replay_identity!=request.replay_identity{unresolved.insert(c.case_id.clone());uncertainty.insert(format!("{}:replay-identity",c.case_id));}else{match c.status.as_str(){"resolved" if !c.evidence_digests.is_empty()=>{resolved.insert(c.case_id.clone());},"blocked"|"contradicted"=>{blocked.insert(c.case_id.clone());negative.insert(format!("{}:contradicted",c.case_id));},"measured"=>{unresolved.insert(c.case_id.clone());uncertainty.insert(format!("{}:measured-not-closed",c.case_id));},_=>{unresolved.insert(c.case_id.clone());omissions.insert(format!("{}:not-closed",c.case_id));}}}}seen.clear();let mut peer_order=Vec::new();let mut qualified=BTreeSet::new();let mut missing=BTreeSet::new();for p in &peers{if !seen.insert(p.peer_id.clone())||!ne(&p.peer_id)||!ne(&p.semantic_profile)||!dig(&p.closure_digest)||!dig(&p.replay_identity)||!p.local||!p.aggregate_only{return Err(LimitationClosureError::Invalid("peer identity, digest, or locality is invalid".into()))}peer_order.push(p.peer_id.clone());if p.semantic_profile!=request.semantic_profile||p.replay_identity!=request.replay_identity||p.evidence_state!="qualified"{missing.insert(p.peer_id.clone());uncertainty.insert(format!("{}:peer-not-qualified",p.peer_id));}else{qualified.insert(p.peer_id.clone());}}if qualified.len()<(request.minimum_peer_quorum as usize){uncertainty.insert(format!("peer-quorum:{}/{}",qualified.len(),request.minimum_peer_quorum));}let global=!request.policy_allowed||!request.protected_closure||!request.federation_approved||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty();if global{blocked.extend(case_order.iter().cloned());resolved.clear();unresolved.clear();}let disposition=if global{"blocked"}else if resolved.is_empty(){"unknown"}else if !unresolved.is_empty()||!blocked.is_empty()||qualified.len()<(request.minimum_peer_quorum as usize){"partial"}else{"closed"};if disposition!="closed"{omissions.insert("request:closure-incomplete".into());}let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"semantic_profile":request.semantic_profile,"disposition":disposition,"case_order":case_order,"resolved_order":resolved.into_iter().collect::<Vec<_>>(),"unresolved_order":unresolved.into_iter().collect::<Vec<_>>(),"blocked_order":blocked.into_iter().collect::<Vec<_>>(),"peer_order":peer_order,"qualified_peer_order":qualified.into_iter().collect::<Vec<_>>(),"missing_peer_order":missing.into_iter().collect::<Vec<_>>(),"omission_order":omissions.into_iter().collect::<Vec<_>>(),"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|LimitationClosureError::Output(e.to_string()))?;payload["closure_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-limitation-closure:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["omission_order"],"provenance_digests":Vec::<ContentHash>::new(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="closed"{vec![format!("exchange:limitation-digests:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:LimitationClosureCard7=serde_json::from_value(payload).map_err(|e|LimitationClosureError::Output(e.to_string()))?;out.validate()?;Ok(out)}
